query:
create table if not exists public.customer_favourites (
  user_id uuid not null references auth.users(id) on delete cascade,
  menu_item_id text not null references public.restaurant_menu_items(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, menu_item_id)
);

alter table public.customer_favourites enable row level security;

drop policy if exists customer_favourites_select_own on public.customer_favourites;
create policy customer_favourites_select_own
  on public.customer_favourites
  for select
  to authenticated
  using (auth.uid() = user_id);

drop policy if exists customer_favourites_insert_own on public.customer_favourites;
create policy customer_favourites_insert_own
  on public.customer_favourites
  for insert
  to authenticated
  with check (auth.uid() = user_id);

drop policy if exists customer_favourites_delete_own on public.customer_favourites;
create policy customer_favourites_delete_own
  on public.customer_favourites
  for delete
  to authenticated
  using (auth.uid() = user_id);
